function setMode(m){mode=m;render();}
function enter(n){if(Sudoku.digitState(state.values,n).disabled){message(`Cyfra ${n} występuje już 9 razy na planszy. Usuń lub cofnij wpis, aby użyć jej ponownie.`);return;}if(mode==='note'&&state.values[selected]){message('Aby dodać kandydatów, najpierw usuń liczbę z tego pola.');return;}change(()=>{if(mode==='value'){Sudoku.placeValue(state,selected,n);}else{const a=state.notes[selected];state.notes[selected]=a.includes(n)?a.filter(x=>x!==n):[...a,n].sort();}});message(mode==='note'?'Zmieniono kandydatów w wybranym polu.':'Wpisano liczbę i zaktualizowano kandydatów w wierszu, kolumnie i kwadracie 3 × 3.');}
