$('redo').onclick=()=>{if(future.length){clearHint();history.push(JSON.stringify({state,initial}));const next=JSON.parse(future.pop());state=next.state;initial=next.initial;save();render();message('Przywrócono ostatnią cofniętą zmianę.');}};
