for(const event of ['pointerup','pointercancel','lostpointercapture'])$('image-preview').addEventListener(event,()=>{cropDrag=null;});
function fineRotatePhoto(){if(!originalPhoto||ocrBusy)return;const angle=Number($('photo-angle').value),c=document.createElement('canvas');c.width=originalPhoto.width;c.height=originalPhoto.height;const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.translate(c.width/2,c.height/2);ctx.rotate(angle*Math.PI/180);ctx.drawImage(originalPhoto,-c.width/2,-c.height/2);photo=c;$('photo-angle-value').textContent=angle.toFixed(1)+'°';drawPhoto();$('ocr-review').hidden=true;$('apply-image').hidden=true;}
