async function rotatePhoto(direction){if(!photo||ocrBusy)return;try{const c=document.createElement('canvas');c.width=photo.height;c.height=photo.width;const ctx=c.getContext('2d');ctx.translate(c.width/2,c.height/2);ctx.rotate(direction*Math.PI/2);ctx.drawImage(photo,-photo.width/2,-photo.height/2);await openPhoto(c);}catch(error){$('ocr-status').textContent='Nie udało się obrócić zdjęcia. Spróbuj ponownie.';}}
