for(const id of ['crop-size','crop-x','crop-y'])$(id).oninput=()=>{drawPhoto();$('ocr-review').hidden=true;$('apply-image').hidden=true;};
function showImageReview(){ const thumbnail=$('ocr-thumbnail'),context=thumbnail.getContext('2d'),region=crop();context.fillStyle='white';context.fillRect(0,0,thumbnail.width,thumbnail.height);context.drawImage(photo,region.x,region.y,region.size,region.size,0,0,thumbnail.width,thumbnail.height);$('image-source').open=false;$('image-title').textContent='Sprawdź rozpoznaną planszę';$('ocr-review').hidden=false;$('apply-image').hidden=false;$('edit-image-crop').hidden=false;$('recognize').textContent='Rozpoznaj ponownie';$('recognize').classList.replace('primary','secondary');$('ocr-review-title').focus({preventScroll:true});$('image-dialog').scrollTop=0;}
