async function importPhotoFile(e){const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Obraz jest zbyt duży. Wybierz plik do 20 MB.');await openPhoto(file);}catch(err){message('Nie udało się otworzyć obrazu. '+err.message);}finally{e.target.value='';}}
$('image-file').onchange=importPhotoFile;
$('camera-file').onchange=importPhotoFile;
